"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["2691"],{3527(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>u,frontMatter:()=>r,contentTitle:()=>h,toc:()=>d,assets:()=>l});var o=JSON.parse('{"id":"m2-models-quantization-api/lesson","title":"Lesson: Models, Quantization & the OpenAI-Compatible Contract","description":"Your team has decided to self-host a model. Maybe the data cannot leave your network, maybe the hosted bill got too big, maybe you just want control. Either way the question lands on your desk: which model do we run, and will it fit the box we have? You open a model hub and there are thousands of them. The same model comes in a dozen versions with cryptic tags \u2014 q4km, q8_0, fp16, awq. One says 0.6B, another says 7B, another 70B. You have eight gigabytes of memory on the machine you were given. Nothing on the page tells you, in plain terms, which one fits and what you give up by squeezing it in.","source":"@site/docs/m2-models-quantization-api/lesson.md","sourceDirName":"m2-models-quantization-api","slug":"/m2-models-quantization-api/lesson","permalink":"/305-llmops/docs/m2-models-quantization-api/lesson","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Lesson: Models, Quantization & the OpenAI-Compatible Contract"},"sidebar":"courseSidebar","previous":{"title":"Deep Dive (Part 2)","permalink":"/305-llmops/docs/m1-how-llms-work/deep-dive"},"next":{"title":"Lab: Two Quants Side by Side & the Raw API Tour","permalink":"/305-llmops/docs/m2-models-quantization-api/lab"}}'),s=n(4848),i=n(8453),a=n(7684);let r={sidebar_position:1,title:"Lesson: Models, Quantization & the OpenAI-Compatible Contract"},h="Models, Quantization & the OpenAI-Compatible Contract",l={},d=[{value:"Memory math \u2014 a model is mostly weights, and weights have a size",id:"memory-math--a-model-is-mostly-weights-and-weights-have-a-size",level:2},{value:"Quantization \u2014 the photo at lower resolution",id:"quantization--the-photo-at-lower-resolution",level:2},{value:"Reading a model card \u2014 the label on the medicine strip",id:"reading-a-model-card--the-label-on-the-medicine-strip",level:2},{value:"Engine and format \u2014 which runner can run this model",id:"engine-and-format--which-runner-can-run-this-model",level:2},{value:"The OpenAI-compatible contract \u2014 a call centre with no memory",id:"the-openai-compatible-contract--a-call-centre-with-no-memory",level:2},{value:"Reading a response: usage, streaming, and finish reasons",id:"reading-a-response-usage-streaming-and-finish-reasons",level:3},{value:"The API is a moving target",id:"the-api-is-a-moving-target",level:3},{value:"What you&#39;ll do next",id:"what-youll-do-next",level:2}];function c(e){let t={admonition:"admonition",blockquote:"blockquote",code:"code",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",mermaid:"mermaid",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"models-quantization--the-openai-compatible-contract",children:"Models, Quantization & the OpenAI-Compatible Contract"})}),"\n",(0,s.jsxs)(t.p,{children:["Your team has decided to self-host a model. Maybe the data cannot leave your network, maybe the hosted bill got too big, maybe you just want control. Either way the question lands on your desk: which model do we run, and will it fit the box we have? You open a model hub and there are thousands of them. The same model comes in a dozen versions with cryptic tags \u2014 ",(0,s.jsx)(t.code,{children:"q4_k_m"}),", ",(0,s.jsx)(t.code,{children:"q8_0"}),", ",(0,s.jsx)(t.code,{children:"fp16"}),", ",(0,s.jsx)(t.code,{children:"awq"}),". One says 0.6B, another says 7B, another 70B. You have eight gigabytes of memory on the machine you were given. Nothing on the page tells you, in plain terms, which one fits and what you give up by squeezing it in."]}),"\n",(0,s.jsx)(t.p,{children:"That is the job of this module. By the end you will look at a model on a hub and read it the way you read a spec sheet: how much memory it needs, what you traded away to make it smaller, what the licence lets you do with it, and which serving engine can run it. And you will speak to it properly \u2014 through the one API that every backend in this course understands, the same API your ChatGPT client speaks under the hood. We build the reading skill first, then the speaking skill."}),"\n",(0,s.jsx)(t.p,{children:"In M1 you learned what a model does at runtime \u2014 tokens, the prefill and decode phases, the KV cache that sets your capacity. This module is about the model itself as an artefact you pick, size, and deploy. Everything here builds on that runtime picture, so we will not re-explain it; we will use it."}),"\n","\n",(0,s.jsx)(a.A,{src:"decks/m2-concepts.html",title:"M2 \u2014 Models, Quantization & the OpenAI-Compatible Contract"}),"\n",(0,s.jsx)(t.h2,{id:"memory-math--a-model-is-mostly-weights-and-weights-have-a-size",children:"Memory math \u2014 a model is mostly weights, and weights have a size"}),"\n",(0,s.jsx)(t.p,{children:"Start with the first question, because it is the one that stops a deployment cold: will this model fit?"}),"\n",(0,s.jsxs)(t.p,{children:["A model is, at heart, a giant pile of numbers called ",(0,s.jsx)(t.strong,{children:"weights"}),', that is the learned values that make the model do what it does. When people say a model is "0.6B" or "7B" or "70B", the B means billion, and the number is roughly how many of these weights the model has. That is the ',(0,s.jsx)(t.strong,{children:"parameter count"}),". More parameters usually means a more capable model, and it always means more numbers to store."]}),"\n",(0,s.jsxs)(t.p,{children:["Now, storing a number takes space, and how much space depends on the ",(0,s.jsx)(t.strong,{children:"precision"}),", that is how many bits you spend on each number. This is the whole game. A number stored in full 16-bit precision (called FP16, that is 16-bit floating point) takes 2 bytes. The same number stored in 8-bit takes 1 byte. In 4-bit, half a byte. So the memory a model's weights need is simply:"]}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsx)(t.p,{children:"weights memory \u2248 number of parameters into bytes per parameter"}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"Think of it like a photo library on your phone. The number of photos is fixed \u2014 that is your parameter count. But you can store each photo at full resolution or compressed. Full resolution looks best and fills the disk; compressed fits far more but each photo loses a little detail. The count of photos does not change. What changes is how many bytes you spend on each one. A model is the same: the parameter count is fixed by the model, but you choose how many bytes to spend per parameter."}),"\n",(0,s.jsxs)(t.p,{children:["Let us do the sum for the real course model. In M1 you ran ",(0,s.jsx)(t.code,{children:"qwen3:0.6b"}),". Its actual parameter count \u2014 you will read this off the model card in the lab \u2014 is about 751.63 million, not exactly 0.6 billion (branding rounds down; the real count is bigger, and reading the true number is a skill this module teaches). Here is what those parameters cost at three precisions:"]}),"\n",(0,s.jsxs)(t.table,{children:[(0,s.jsx)(t.thead,{children:(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.th,{children:"Precision"}),(0,s.jsx)(t.th,{children:"Bytes per parameter"}),(0,s.jsx)(t.th,{children:"Weights memory (751.63M params)"}),(0,s.jsx)(t.th,{children:"What it is"})]})}),(0,s.jsxs)(t.tbody,{children:[(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"FP16"}),(0,s.jsx)(t.td,{children:"2"}),(0,s.jsx)(t.td,{children:"~1.4 GB"}),(0,s.jsx)(t.td,{children:"full 16-bit, the original release format"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Q8 (INT8)"}),(0,s.jsx)(t.td,{children:"~1"}),(0,s.jsx)(t.td,{children:"~0.8 GB"}),(0,s.jsx)(t.td,{children:"8-bit, near-original quality"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Q4"}),(0,s.jsx)(t.td,{children:"~0.5"}),(0,s.jsx)(t.td,{children:"~0.5 GB"}),(0,s.jsx)(t.td,{children:"4-bit, the common laptop default"})]})]})]}),"\n",(0,s.jsx)(t.p,{children:"The exact figures shift a little because quantized formats keep some parts at higher precision \u2014 you will see the real disk sizes in the lab (about 832 MB for Q8, about 522 MB for Q4). But the shape is what matters: cut the bytes per parameter and you cut the memory, close to proportionally. That is why a 4-bit model fits a laptop and a 16-bit one may not."}),"\n",(0,s.jsx)(t.p,{children:"But weights are not the whole memory bill. Remember M1: when you actually serve the model, memory goes to three things."}),"\n",(0,s.jsx)(t.mermaid,{value:'flowchart TB\n  subgraph BOX["memory of a serving box"]\n    direction TB\n    W["<b>weights</b><br/>params \xd7 bytes/param<br/>(fixed once you pick the quant)"]\n    R["<b>runtime buffers</b><br/>the engine\'s working memory<br/>(activations, scratch space)"]\n    K["<b>KV cache</b><br/>per-token cost \xd7 tokens \xd7 concurrent requests<br/>(the M1 capacity number)"]\n  end\n  W --- R --- K'}),"\n",(0,s.jsxs)(t.p,{children:["This is why, in the lab, the size Ollama reports as ",(0,s.jsx)(t.em,{children:"loaded"})," (about 1.0 GB for Q4, 1.3 GB for Q8) is bigger than the size on disk. Loaded memory is weights plus the engine's runtime buffers plus a reservation for the KV cache of the context you configured. When you size a box, you are budgeting for all three, not just the weights. Quantization shrinks the weights term \u2014 the biggest and most fixed one \u2014 which is exactly why it is the first lever you reach for."]}),"\n",(0,s.jsx)(t.admonition,{title:"The habit to carry out of this section",type:"tip",children:(0,s.jsx)(t.p,{children:"Before you deploy any model, do the back-of-envelope sum: parameters into bytes-per-parameter gives you the weights, then add runtime buffers and the KV cache for your context (the M1 math). If that total does not fit your box, your options are a smaller model, a lower precision, or a shorter context \u2014 and now you know which lever moves what."})}),"\n",(0,s.jsx)(t.h2,{id:"quantization--the-photo-at-lower-resolution",children:"Quantization \u2014 the photo at lower resolution"}),"\n",(0,s.jsx)(t.p,{children:"You just used quantization without naming the mechanism. Let us name it, analogy first."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Quantization"})," is storing the model's weights at lower precision \u2014 fewer bits per number \u2014 to make the model smaller. The word sounds heavy but the idea is the one you already met: same photo, lower resolution."]}),"\n",(0,s.jsxs)(t.p,{children:["Print a photograph at 300 dots per inch and it looks sharp; you cannot see the individual dots. Print the same photo at 72 dots per inch and it is still clearly the same photograph \u2014 the same faces, the same scene \u2014 but look closely and the fine detail is coarser, edges a little blocky. You used far less ink and the print is much smaller. You did not change ",(0,s.jsx)(t.em,{children:"what"}),' the picture is. You changed how finely each part of it is recorded. Quantization does exactly this to a model\'s weights: it records each weight more coarsely, so the model is smaller, and it is still the same model \u2014 but the finest detail of its "knowledge" is recorded less precisely.']}),"\n",(0,s.jsxs)(t.p,{children:["Here is the part that surprises most people, and it is a direct callback to M1. You would expect the smaller, lower-precision model to be ",(0,s.jsx)(t.em,{children:"worse"})," at everything, including speed. It is not. On the machines this course runs on, ",(0,s.jsx)(t.strong,{children:"the 4-bit model decodes faster than the 8-bit one."})," In the lab you will measure it: Q4 at roughly 180 tokens per second, Q8 at roughly 140 \u2014 the 4-bit model close to 30% faster (your exact numbers will differ run to run; the gap is the invariant)."]}),"\n",(0,s.jsxs)(t.p,{children:["Why? Because of the one fact you locked in M1: decode is ",(0,s.jsx)(t.strong,{children:"memory-bandwidth-bound"}),". Each token the model writes, it must move the relevant weights in and out of memory. The limit is not raw compute; it is how many bytes you shift per step. A 4-bit weight is half the bytes of an 8-bit weight. Fewer bytes to move per token means more tokens per second. So quantization does not trade quality for speed \u2014 on bandwidth-bound decode it ",(0,s.jsx)(t.em,{children:"gains"})," speed. What it trades is quality headroom."]}),"\n",(0,s.jsx)(t.p,{children:"And that trade must be read honestly, which is the second reason this section matters. On this tiny 0.6B model, the quality gap between Q4 and Q8 is subtle \u2014 in the lab you will ask both the same everyday questions and struggle to tell them apart. That is real, and it is why Q4 is a fine default for a small model. But do not over-learn it. On a large model, or one pushed to a very aggressive quantization (3-bit, 2-bit), the loss becomes visible \u2014 more so on hard reasoning and on exact recall than on casual chat. The rule to carry: quantization always costs some quality; how much you can see depends on the model size and how far you push it. You test on your own task, you do not assume."}),"\n",(0,s.jsx)(t.admonition,{title:"The trade, stated plainly",type:"note",children:(0,s.jsxs)(t.p,{children:["Lower precision \u2192 smaller weights \u2192 faster bandwidth-bound decode and a smaller memory footprint \u2192 ",(0,s.jsx)(t.em,{children:"some"})," loss of quality headroom, subtle on small models, more visible on large ones or aggressive quants. You choose the point on that curve for your task, and you verify it, rather than reaching for FP16 by reflex or Q4 by reflex."]})}),"\n",(0,s.jsx)(t.h2,{id:"reading-a-model-card--the-label-on-the-medicine-strip",children:"Reading a model card \u2014 the label on the medicine strip"}),"\n",(0,s.jsxs)(t.p,{children:["You now know a model has a size and a precision. But a model on a hub carries far more than that, and reading it is a skill that saves you from adopting something you cannot legally ship or cannot technically run. The place all of this lives is the ",(0,s.jsx)(t.strong,{children:"model card"}),"."]}),"\n",(0,s.jsx)(t.p,{children:"Think of a strip of medicine from the chemist. Before you take it you read the label: the dose, the expiry, who made it, what it is for, what it interacts with. You do not swallow an unlabelled pill. A model card is that label. Before you adopt a model into production you read: how big it is, how much context it supports, what licence governs it, who published it and from what. Skip the label and you find out the hard way \u2014 a licence that forbids your use case, a context window too small for your documents, a provenance you cannot vouch for in a compliance review."}),"\n",(0,s.jsxs)(t.p,{children:["You do not need a website to read a model card. Ollama ships one into your terminal. In the lab you will run ",(0,s.jsx)(t.code,{children:"ollama show qwen3:0.6b"})," and read these fields:"]}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Parameters"})," \u2014 the real count. It reads ",(0,s.jsx)(t.strong,{children:"751.63M"}),', not "0.6B". The branding rounds; the card does not. When you are sizing memory, you use the real number.']}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Context length"})," \u2014 the model card reports ",(0,s.jsx)(t.strong,{children:"40960"}),", the maximum context this model was built to handle. But the context Ollama actually ",(0,s.jsx)(t.em,{children:"runs"})," it at (visible in ",(0,s.jsx)(t.code,{children:"ollama ps"}),') is smaller \u2014 4096 by default. That gap matters, and here is why: the KV cache from M1 grows with context. At the full 40960-token context, the KV cache alone would pin roughly 4.5 GB of memory (40960 tokens into the ~112 KiB-per-token figure you computed in M1). You do not pay for context you do not configure. So "the model supports 40k context" and "I am running it at 40k context" are two very different memory bills, and confusing them is how people run out of memory. You configure the context you need, not the maximum the card advertises.']}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Quantization"})," \u2014 the field that says ",(0,s.jsx)(t.code,{children:"Q4_K_M"})," on the default and ",(0,s.jsx)(t.code,{children:"Q8_0"})," on the variant. Same card, one field different. This is where you confirm which precision you actually pulled."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Licence"})," \u2014 what you are legally allowed to do with the model. This one gets its own paragraph."]}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"The licence is the field engineers skip and lawyers do not. Models come under different licence classes, and they permit very different things:"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Apache-2.0 / MIT"})," \u2014 genuinely permissive. You may use commercially, fine-tune, and redistribute, with minimal conditions. Qwen3 (the course model) is Apache-2.0, which is why this course can build on it freely \u2014 and why, when you fine-tune it in M6 and package and redistribute it in M7, you are within your rights."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Community / custom licences"})," (for example the Llama licence) \u2014 usable commercially but with conditions: acceptable-use clauses, sometimes a size threshold above which you need a separate agreement, sometimes naming or attribution requirements."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Research-only / non-commercial"})," \u2014 you may experiment but you may not ship it in a product."]}),"\n"]}),"\n",(0,s.jsxs)(t.p,{children:["The point is not to memorise licences. It is to read the field ",(0,s.jsx)(t.em,{children:"before"})," you build on a model, because the cost of finding out later \u2014 after you have fine-tuned and shipped \u2014 is a rebuild, not a config change."]}),"\n",(0,s.jsx)(t.h2,{id:"engine-and-format--which-runner-can-run-this-model",children:"Engine and format \u2014 which runner can run this model"}),"\n",(0,s.jsx)(t.p,{children:"You have picked a model, checked its size, read its licence. One question remains before you can serve it: what format is it in, and which engine runs that format? Getting this pairing wrong is the most common early stumble \u2014 you download a model, point your serving engine at it, and it refuses to load, because the format and the engine do not match."}),"\n",(0,s.jsx)(t.p,{children:"Models ship in two dominant formats, and each has its natural engine:"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"GGUF"})," \u2014 a single-file format built for running quantized models efficiently on CPU and on Apple Silicon (Metal). This is what ",(0,s.jsx)(t.strong,{children:"Ollama"})," and ",(0,s.jsx)(t.strong,{children:"llama.cpp"})," consume. The ",(0,s.jsx)(t.code,{children:"qwen3:0.6b"})," you have been running is GGUF. It is the format that makes laptop-class serving practical, which is exactly why this course starts here."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"safetensors"})," \u2014 the format models are usually released in, holding full-precision (FP16) weights or GPU-oriented quantizations (AWQ, GPTQ \u2014 you meet those in the Deep Dive). This is what ",(0,s.jsx)(t.strong,{children:"vLLM"})," consumes, the production GPU serving engine you stand up in M3."]}),"\n"]}),"\n",(0,s.jsx)(t.mermaid,{value:'flowchart LR\n  M["a model you want to serve"] --\x3e F{"what format<br/>is it in?"}\n  F --\x3e|GGUF<br/>quantized, single file| G["Ollama \xb7 llama.cpp<br/><i>CPU / Apple Silicon</i><br/>(this course, M1\u2013M2)"]\n  F --\x3e|safetensors<br/>FP16 / AWQ / GPTQ| V["vLLM<br/><i>GPU serving</i><br/>(M3 onward)"]'}),"\n",(0,s.jsx)(t.p,{children:'Read this as a decision framework, not a rule to memorise. When you are handed a model, your first two questions are "what format?" and "what am I serving it on?" \u2014 and those two answers pick your engine. GGUF on a laptop CPU means Ollama or llama.cpp. safetensors on a GPU means vLLM. In this module you prove the GGUF-and-Ollama side, live, on your own machine. In M3 you serve the identical model through vLLM and swap engines under an unchanged client \u2014 which only works because of the last idea in this lesson: the one API contract that sits above every engine.'}),"\n",(0,s.jsx)(t.h2,{id:"the-openai-compatible-contract--a-call-centre-with-no-memory",children:"The OpenAI-compatible contract \u2014 a call centre with no memory"}),"\n",(0,s.jsxs)(t.p,{children:["Everything above is about picking and sizing the model. This last section is about talking to it \u2014 and it is the load-bearing idea for the rest of the course, because every backend you serve, from Ollama today to vLLM in production, speaks the same API. Your client code never changes when the engine underneath changes. That is by design, and the design is the ",(0,s.jsx)(t.strong,{children:"OpenAI-compatible API"}),": the ",(0,s.jsx)(t.code,{children:"/v1/chat/completions"})," endpoint your ChatGPT client speaks, that every serious serving engine now implements."]}),"\n",(0,s.jsxs)(t.p,{children:["The single most important property of this API, and the one that surprises engineers coming from stateful systems, is that ",(0,s.jsx)(t.strong,{children:"it is stateless"}),". The model server remembers nothing between calls."]}),"\n",(0,s.jsxs)(t.p,{children:["Picture a call centre where every call is answered by a different agent who has never spoken to you before and keeps no notes. If you rang yesterday about a broken connection and you ring again today, the new agent knows nothing about it. So to continue the conversation, ",(0,s.jsx)(t.em,{children:"you"}),' must repeat the whole story every single call: "Yesterday I reported my connection dropping, you asked me to restart the router, I did, and it is still dropping." Only then can they help. The agent holds no memory; the caller carries the context.']}),"\n",(0,s.jsxs)(t.p,{children:["The chat API works exactly like this. Every request is answered fresh, with no memory of the last one. So to have a multi-turn conversation, the ",(0,s.jsx)(t.em,{children:"client"})," resends the entire history every time. This is why a chat request is a ",(0,s.jsx)(t.strong,{children:"list"})," of messages, not a single string:"]}),"\n",(0,s.jsx)(t.pre,{children:(0,s.jsx)(t.code,{className:"language-json",children:'{\n  "model": "qwen3:0.6b",\n  "messages": [\n    {"role": "system",    "content": "You are a concise assistant."},\n    {"role": "user",      "content": "What is the capital of France?"},\n    {"role": "assistant", "content": "Paris."},\n    {"role": "user",      "content": "And its population?"}\n  ]\n}\n'})}),"\n",(0,s.jsxs)(t.p,{children:['Look at what happened. To ask the follow-up "And its population?", the client had to resend the system instruction, the first question, ',(0,s.jsx)(t.em,{children:"and the model's own previous answer"})," (the ",(0,s.jsx)(t.code,{children:"assistant"}),' turn) back to the server. The model did not remember saying "Paris" \u2014 the client reminded it. Three roles do this work:']}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"system"})," \u2014 the standing instruction that frames every turn (tone, role, rules)."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"user"})," \u2014 what the person said."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"assistant"})," \u2014 what the model said before, fed back in so the model can see its own prior turns."]}),"\n"]}),"\n",(0,s.jsxs)(t.p,{children:['This statelessness is not a limitation to work around; it is the property that makes serving scale. Because the server holds no session, any request can go to any replica \u2014 there is no "your conversation lives on server 3". It also means the ops consequence you will feel directly: ',(0,s.jsx)(t.strong,{children:"every turn resends the whole history, so a long conversation sends more and more tokens each turn"}),", and tokens are the meter (M1). A ten-turn chat is not ten cheap calls; the tenth call carries all nine turns before it."]}),"\n",(0,s.jsx)(t.h3,{id:"reading-a-response-usage-streaming-and-finish-reasons",children:"Reading a response: usage, streaming, and finish reasons"}),"\n",(0,s.jsxs)(t.p,{children:["When you call the API without streaming (",(0,s.jsx)(t.code,{children:'"stream": false'}),"), you get one JSON body back. Three parts of it earn your attention as an operator:"]}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:(0,s.jsx)(t.code,{children:"usage"})})," \u2014 the billing meter, made explicit. It reports ",(0,s.jsx)(t.code,{children:"prompt_tokens"})," (what prefill read), ",(0,s.jsx)(t.code,{children:"completion_tokens"})," (what decode wrote), and ",(0,s.jsx)(t.code,{children:"total_tokens"}),". This is the exact number a hosted provider charges you on, and the exact number that filled your KV cache. When a bill or a latency number surprises you, this field is where you look first."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:(0,s.jsx)(t.code,{children:"choices[].message"})})," \u2014 the answer itself, with its ",(0,s.jsx)(t.code,{children:"role"})," (",(0,s.jsx)(t.code,{children:"assistant"}),") and ",(0,s.jsx)(t.code,{children:"content"}),"."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:(0,s.jsx)(t.code,{children:"choices[].finish_reason"})})," \u2014 ",(0,s.jsx)(t.em,{children:"why"})," the model stopped. ",(0,s.jsx)(t.code,{children:"stop"})," means it finished naturally. ",(0,s.jsx)(t.code,{children:"length"})," means it hit your ",(0,s.jsx)(t.code,{children:"max_tokens"}),' cap and was cut off mid-thought \u2014 a truncated answer, not a complete one. Reading this field is how you tell "the model finished" from "the model got guillotined", which look identical if you only read the text.']}),"\n"]}),"\n",(0,s.jsxs)(t.p,{children:["When you ",(0,s.jsx)(t.em,{children:"do"})," stream (",(0,s.jsx)(t.code,{children:'"stream": true'}),"), the answer arrives as many small chunks over the wire \u2014 that drip of words you watched in M1. Each chunk carries a ",(0,s.jsx)(t.code,{children:"delta"})," with the next piece of ",(0,s.jsx)(t.code,{children:"content"}),", and the final chunk carries the ",(0,s.jsx)(t.code,{children:"finish_reason"}),". Streaming does not change ",(0,s.jsx)(t.em,{children:"what"})," the model produces; it changes ",(0,s.jsx)(t.em,{children:"when"})," you see it \u2014 first token fast, rest as they come. That is why a chat UI feels responsive even on a long answer: it shows you the decode loop live rather than waiting for the whole thing."]}),"\n",(0,s.jsxs)(t.p,{children:['One honest wrinkle, and it is a callback to M1: "OpenAI-compatible" is a promise every engine ',(0,s.jsx)(t.em,{children:"mostly"})," keeps, not perfectly. In M1 you saw Ollama's streaming route surface the model's reasoning in an extra ",(0,s.jsx)(t.code,{children:"delta.reasoning"})," field that the OpenAI spec does not define. That is ",(0,s.jsx)(t.strong,{children:"compatibility drift"})," \u2014 an engine adding or shaping fields its own way. It is minor here, but it is real, and it grows as engines add features (thinking modes, tool calls) faster than the shared spec settles. You keep this in mind when you write a client meant to work against more than one backend."]}),"\n",(0,s.jsx)(t.h3,{id:"the-api-is-a-moving-target",children:"The API is a moving target"}),"\n",(0,s.jsxs)(t.p,{children:["The ",(0,s.jsx)(t.code,{children:"/v1/chat/completions"})," shape you just learned is the workhorse and will be for years. But it is not frozen. OpenAI has introduced a newer ",(0,s.jsx)(t.strong,{children:"Responses API"})," with a different shape aimed at tool-using, multi-step \"agentic\" interactions \u2014 and provider-native APIs (Anthropic's, Google's) differ again in their own ways. Tool-call semantics in particular \u2014 how the model asks to call a function and how you feed the result back \u2014 differ enough between APIs that a client written naively against one breaks against another. The Deep Dive reads these differences properly."]}),"\n",(0,s.jsxs)(t.p,{children:["For now, hold two facts. First, Chat Completions is the stable contract this course builds on end to end. Second, when you have many models behind many slightly-different APIs, the pattern that absorbs the drift is a ",(0,s.jsx)(t.strong,{children:"gateway"})," \u2014 one endpoint in front that presents a single API and translates to each backend. You stand one up in M12. This lesson is where you learn ",(0,s.jsx)(t.em,{children:"why"})," it exists: the API contract is real, load-bearing, and moving, all at once."]}),"\n",(0,s.jsx)(t.h2,{id:"what-youll-do-next",children:"What you'll do next"}),"\n",(0,s.jsxs)(t.p,{children:["In the lab you will pull the same course model at a second precision (",(0,s.jsx)(t.code,{children:"qwen3:0.6b-q8_0"}),") and put the two quants side by side on your own machine: their disk sizes, their loaded sizes, their decode speed \u2014 where you will watch the 4-bit model come out ",(0,s.jsx)(t.em,{children:"faster"})," \u2014 and their answer quality on the same everyday questions, read honestly. You will open the terminal model card with ",(0,s.jsx)(t.code,{children:"ollama show"})," and read every field this lesson named. Then you will take the full raw tour of ",(0,s.jsx)(t.code,{children:"/v1/chat/completions"}),": the ",(0,s.jsx)(t.code,{children:"usage"})," meter, a multi-turn request that proves the API is stateless by making you resend the history, a streamed response chunk by chunk, and a ",(0,s.jsx)(t.code,{children:"finish_reason: length"})," you trigger on purpose. You finish by reclaiming the Q8 model's disk, leaving your course model clean for M3."]}),"\n",(0,s.jsx)(t.p,{children:"The skill you leave with is reading a model as an artefact \u2014 its size, its trade-offs, its licence, its format \u2014 and speaking to it through the one contract that outlives any single engine. That is the ground the rest of the course stands on."})]})}function u(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},7684(e,t,n){n.d(t,{A:()=>i});var o=n(4848);n(6540);var s=n(6497);function i({src:e,title:t="Slides"}){let n=(0,s.Ay)(e);return(0,o.jsxs)("div",{className:"deck_nWXz",children:[(0,o.jsxs)("div",{className:"bar_dOoE",children:[(0,o.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",t]}),(0,o.jsx)("a",{className:"full_PrDQ",href:n,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,o.jsx)("div",{className:"frame_M4DO",children:(0,o.jsx)("iframe",{src:n,title:t,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var o=n(6540);let s={},i=o.createContext(s);function a(e){let t=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);